using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations ---------------------------------------------------

/// <summary>Tools the agent can invoke during its research loop.</summary>
static class ResearchTools
{
    private static readonly List<string> s_notes = [];
    private static readonly HttpClient s_http = new();

    [Description("Search the web for a query and return a snippet of results. Use this to find information on a topic.")]
    public static async Task<string> WebSearch([Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍 Searching: {query}");
        Console.ResetColor();

        // Use DuckDuckGo instant-answer API (no key required)
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await s_http.GetStringAsync(url);

            // Pull the Abstract or RelatedTopics text from the JSON response
            using var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var abstractText = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                return $"[DuckDuckGo Abstract]\n{abstractText}";

            // Fall back to related topics
            var related = root.GetProperty("RelatedTopics");
            var snippets = new List<string>();
            foreach (var item in related.EnumerateArray())
            {
                if (item.TryGetProperty("Text", out var text) && !string.IsNullOrWhiteSpace(text.GetString()))
                {
                    snippets.Add(text.GetString()!);
                    if (snippets.Count >= 5) break;
                }
            }

            return snippets.Count > 0
                ? $"[DuckDuckGo Related Topics]\n{string.Join("\n\n", snippets)}"
                : "No results found. Try a different or more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed ({ex.Message}). Try rephrasing the query.";
        }
    }

    [Description("Save a research note. Use this to record key facts, findings, or quotes you want to remember.")]
    public static string SaveNote([Description("The note content to save")] string note)
    {
        s_notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note #{s_notes.Count} saved ({note.Length} chars)");
        Console.ResetColor();
        return $"Note #{s_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n---\n",
            s_notes.Select((n, i) => $"Note #{i + 1}:\n{n}"));
    }
}

// --- Main entry point --------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    return 1;
}

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🤖 Research Agent — investigating: \"{topic}\"\n");

// Build the chat client with tool support
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new[]
{
    AIFunctionFactory.Create(ResearchTools.WebSearch),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the given topic
        using the tools available to you, then produce a well-organized summary.

        Workflow:
        1. Search the web with several varied queries to gather broad information.
        2. Save important facts and findings as notes.
        3. After you have gathered enough information (at least 3 searches), retrieve
           your notes and write a final summary.
        4. Present the summary to the user as your final answer. The summary should
           include key findings, organized by theme, with a short conclusion.

        Be thorough but concise. Cite sources where possible.
        """),
    new(ChatRole.User, $"Please research the following topic and summarize your findings:\n\n{topic}"),
];

// Agent loop — keep going until the model produces a final answer with no tool calls
const int maxIterations = 20;
for (int i = 0; i < maxIterations; i++)
{
    var response = await client.GetResponseAsync(messages, chatOptions);

    // Append assistant response to history
    messages.AddRange(response.Messages);

    // If the model didn't invoke any tools, we have the final answer
    var hasToolCalls = response.Messages
        .Any(m => m.Contents.OfType<FunctionCallContent>().Any());

    if (!hasToolCalls)
    {
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("\n════════════════════ Research Summary ════════════════════\n");
        Console.ResetColor();

        var answer = response.Messages
            .SelectMany(m => m.Contents.OfType<TextContent>())
            .Select(tc => tc.Text)
            .FirstOrDefault(t => !string.IsNullOrWhiteSpace(t));

        Console.WriteLine(answer ?? "(No summary produced)");
        Console.WriteLine();
        break;
    }
}

return 0;

// --- Helpers ------------------------------------------------------------------

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrWhiteSpace(input) ? "The history and impact of the Internet" : input;
}

