// --- Tool implementations ---------------------------------------------------

/// <summary>Tools the agent can invoke during its research loop.</summary>
static class ResearchTools
{
    private static readonly List<string> s_notes = [];
    private static readonly HttpClient s_http = new();

    [Description("Search the web for a query and return a snippet of results. Use this to find information on a topic.")]
    public static async Task<string> WebSearch([Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍 Searching: {query}");
        Console.ResetColor();

        // Use DuckDuckGo instant-answer API (no key required)
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await s_http.GetStringAsync(url);

            using var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var abstractText = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                return $"[DuckDuckGo Abstract]\n{abstractText}";

            // Fall back to related topics
            var related = root.GetProperty("RelatedTopics");
            var snippets = new List<string>();
            foreach (var item in related.EnumerateArray())
            {
                if (item.TryGetProperty("Text", out var text) && !string.IsNullOrWhiteSpace(text.GetString()))
                {
                    snippets.Add(text.GetString()!);
                    if (snippets.Count >= 5) break;
                }
            }

            return snippets.Count > 0
                ? $"[DuckDuckGo Related Topics]\n{string.Join("\n\n", snippets)}"
                : "No results found. Try a different or more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed ({ex.Message}). Try rephrasing the query.";
        }
    }

    [Description("Save a research note. Use this to record key facts, findings, or quotes you want to remember.")]
    public static string SaveNote([Description("The note content to save")] string note)
    {
        s_notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note #{s_notes.Count} saved ({note.Length} chars)");
        Console.ResetColor();
        return $"Note #{s_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n---\n",
            s_notes.Select((n, i) => $"Note #{i + 1}:\n{n}"));
    }
}

