1. using System.ComponentModel;
2. using Microsoft.Extensions.AI;
3. using OpenAI;
4. 
5. var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
6. if (string.IsNullOrWhiteSpace(apiKey))
7. {
8.     Console.Error.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
9.     return 1;
10. }
11. 
12. var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
13. 
14. var topic = args.Length > 0
15.     ? string.Join(' ', args)
16.     : PromptForTopic();
17. 
18. Console.WriteLine($"\n🤖 Research Agent — investigating: \"{topic}\"\n");
19. 
20. // Build the chat client with tool support
21. IChatClient client = new OpenAIClient(apiKey)
22.     .GetChatClient(model)
23.     .AsIChatClient()
24.     .AsBuilder()
25.     .UseFunctionInvocation()
26.     .Build();
27. 
28. var tools = new[]
29. {
30.     AIFunctionFactory.Create(ResearchTools.WebSearch),
31.     AIFunctionFactory.Create(ResearchTools.SaveNote),
32.     AIFunctionFactory.Create(ResearchTools.GetNotes),
33. };
34. 
35. var chatOptions = new ChatOptions { Tools = [.. tools] };
36. 
37. List<ChatMessage> messages =
38. [
39.     new(ChatRole.System, """
40.         You are a research agent. Your goal is to thoroughly research the given topic
41.         using the tools available to you, then produce a well-organized summary.
42. 
43.         Workflow:
44.         1. Search the web with several varied queries to gather broad information.
45.         2. Save important facts and findings as notes.
46.         3. After you have gathered enough information (at least 3 searches), retrieve
47.            your notes and write a final summary.
48.         4. Present the summary to the user as your final answer. The summary should
49.            include key findings, organized by theme, with a short conclusion.
50. 
51.         Be thorough but concise. Cite sources where possible.
52.         """),
53.     new(ChatRole.User, $"Please research the following topic and summarize your findings:\n\n{topic}"),
54. ];
55. 
56. // Agent loop — keep going until the model produces a final answer with no tool calls
57. const int maxIterations = 20;
58. for (int i = 0; i < maxIterations; i++)
59. {
60.     var response = await client.GetResponseAsync(messages, chatOptions);
61. 
62.     // Append assistant response to history
63.     messages.AddRange(response.Messages);
64. 
65.     // If the model didn't invoke any tools, we have the final answer
66.     var hasToolCalls = response.Messages
67.         .Any(m => m.Contents.OfType<FunctionCallContent>().Any());
68. 
69.     if (!hasToolCalls)
70.     {
71.         Console.ForegroundColor = ConsoleColor.Green;
72.         Console.WriteLine("\n════════════════════ Research Summary ════════════════════\n");
73.         Console.ResetColor();
74. 
75.         var answer = response.Messages
76.             .SelectMany(m => m.Contents.OfType<TextContent>())
77.             .Select(tc => tc.Text)
78.             .FirstOrDefault(t => !string.IsNullOrWhiteSpace(t));
79. 
